<script setup>
import {computed,onBeforeUnmount,ref,shallowRef} from 'vue';
import {Button,Calendar,Cell,CellGroup,Checkbox,CheckboxGroup,Collapse,CollapseItem,Dialog,DropdownItem,DropdownMenu,Field,Picker,Popup,Radio,RadioGroup,Search,Tab,Tabs,Tag} from 'vant';
import StudentCourseSettings from './StudentCourseSettings.vue';
const props=defineProps({controller:{type:Object,required:true}}),m=shallowRef(props.controller.snapshot()),a=props.controller.actions;
const unsubscribe=props.controller.subscribe(value=>m.value=value);onBeforeUnmount(()=>{unsubscribe();props.controller.destroy();});
const expanded=ref([]),picker=ref(false),unitPicker=ref(false),wordFilter=ref(false),reset=ref(false),confirmed=ref(false),parent=ref(''),parentConfirm=ref(false),game=ref(120),cash=ref(200),enabled=ref(true);
const filterOptions=[{text:'全部词条',value:'all'},{text:'必会词条',value:'required'},{text:'待掌握',value:'pending'},{text:'已达标',value:'mastered'},{text:'选学词条',value:'optional'}];
const groupOptions=computed(()=>[{text:'全部分组',value:'all'},...m.value.groups.map(g=>({text:g.title,value:g.id}))]);
const topicColumns=computed(()=>m.value.topics.map(t=>({text:t.title,value:t.id}))),unitColumns=computed(()=>m.value.units.map(u=>({text:`Unit ${u.number} · ${u.title}`,value:u.id})));
const q=computed(()=>m.value.quiz?.items[m.value.quiz.index]),word=computed(()=>m.value.deck?.kind==='word'?m.value.card:null),day=computed(()=>m.value.studyHistory.days[m.value.date]);
const changes=computed(()=>{const active=new Set(m.value.studyHistory.baseline),rows=[],dates=Object.keys(m.value.studyHistory.days).sort();let index=0;for(let i=m.value.range-1;i>=0;i--){const date=new Date();date.setDate(date.getDate()-i);const key=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;while(index<dates.length&&dates[index]<=key){for(const [id,value] of Object.entries(m.value.studyHistory.days[dates[index]].changes)){if(value)active.add(id);else active.delete(id);}index++;}const d=m.value.studyHistory.days[key];rows.push({date:key,total:active.size,newCount:Object.values(d?.words||{}).filter(r=>r.gained).length,points:Object.values(d?.points||{}).filter(p=>p.total>0&&p.correct/p.total>=.8).length,quizzes:Object.values(d?.quizzes||{}).reduce((sum,q)=>sum+q.attempts,0)});}return rows;});
const curve=computed(()=>{const rows=changes.value,value=row=>m.value.metric==='total'?row.total:m.value.metric==='points'?row.points:row.newCount,max=Math.max(1,...rows.map(value)),y=n=>150-n/max*120;return rows.map((row,i)=>(i?' L':'M')+(35+i/Math.max(1,rows.length-1)*600)+' '+y(value(row))).join('');});
const efficiencyPoints=computed(()=>{const rows=Object.values(m.value.studyHistory.days).flatMap(d=>Object.entries(d.points));const map=new Map();for(const [id,row] of rows){const previous=map.get(id)||{label:row.label,total:0,correct:0,ms:0,timedTotal:0};previous.total+=row.total;previous.correct+=row.correct;previous.ms+=row.timing?.ms||0;previous.timedTotal+=row.timing?.total||0;map.set(id,previous);}return [...map.values()];});
const services=Object.fromEntries(['deepseek','voice'].map(kind=>[kind,{info:signal=>a.settingsInfo(kind,signal),save:value=>a.saveSettings(kind,value),clear:()=>a.clearSettings(kind),test:signal=>a.testSettings(kind,signal)}]));
function source(q){if(q.practiceBasis)return `依据教材考点编写 · ${q.practiceBasis.book} · ${q.practiceBasis.part}`;return q.source?`${q.source.year} · ${q.source.region} · ${q.source.exam} ${q.source.number||''}`:'教师编写 · 应用练习';}
function right(q){return q.type==='choice'?q.opts[q.answer]:q.answer[0];}
function duration(ms){const s=Math.floor((ms||0)/1000);return s<60?s+'秒':s<3600?Math.floor(s/60)+'分'+s%60+'秒':Math.floor(s/3600)+'小时'+Math.floor(s%3600/60)+'分';}
function formatter(item){const d=item.date,key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return {...item,bottomInfo:m.value.studyHistory.days[key]||m.value.learningTime.days[key]?'已学习':''};}
function reward(){if(m.value.rewardLedger){game.value=m.value.rewardLedger.config.gameMinutes;cash.value=m.value.rewardLedger.config.cashYuan;enabled.value=m.value.rewardLedger.config.enabled;}a.open('rewards');}
function selectTopic({selectedValues}){a.feynman(selectedValues[0]);picker.value=false;}
function selectUnit({selectedValues}){const u=m.value.units.find(u=>u.id===selectedValues[0]);unitPicker.value=false;if(u?.entry)a.navigate(new URL(u.entry,new URL('../app-design/',location.href)).href);}
function doReset(){if(a.reset(confirmed.value)){reset.value=false;confirmed.value=false;}}
</script>
<template>
 <nav class="course-return-nav"><Button tag="a" href="../app-design/units.html?subject=english&term=upper" data-growing-back>← 返回上一级</Button></nav>
 <main class="student-unit3-course">
  <header class="unit-header"><div><p class="eyebrow">译林版 · 2025秋新教材 · 八年级上册</p><h1>Unit 3<br>To be a good learner</h1><p class="muted">善于学习 · 副词比较级与最高级 · 反身代词</p><Button class="catalog-link" @click="a.navigate('../app-design/units.html?subject=english&term=upper')">← 英语目录</Button></div><div class="unit-select"><label>切换单元</label><Cell value="Unit 3 · To be a good learner" is-link clickable @click="unitPicker=true"/></div></header>
  <nav class="tabs" aria-label="课堂工具"><Button :aria-current="['library','card'].includes(m.view)?'page':undefined" @click="a.open('library')">单词与默写</Button><Button :aria-current="m.view==='knowledge'?'page':undefined" @click="a.open('knowledge')">阅读与语法</Button><Button :aria-current="m.view==='feynman'?'page':undefined" @click="a.feynman()">概念复述</Button><Button @click="a.navigate('../app-design/english-sentence-demo.html?unit=english-8a-03')">句子闯关</Button><Button @click="a.navigate('../app-design/english-resources.html?unit=english-8a-03')">试卷</Button></nav>
  <p v-if="m.message" role="status">{{m.message}}</p><p v-if="m.storageError" role="alert">{{m.storageError}}</p>
  <section v-if="m.view==='library'" class="course-panel word-library"><h2>{{m.words.length}}个单词与短语（{{Object.keys(m.mastered).length}}/{{m.words.length}}）</h2>
   <div class="word-tools"><Field :model-value="m.search" placeholder="输入英文或中文" aria-label="搜索词条或释义" @update:model-value="a.search"/><Cell :value="filterOptions.find(f=>f.value===m.masteryFilter)?.text" is-link clickable @click="wordFilter=true"/></div>
   <Collapse v-model="expanded" class="unit3-groups"><CollapseItem title="按学习主题查看" name="groups"><Cell v-for="g in groupOptions" :key="g.value" :title="g.text" clickable @click="a.filter(g.value)"/></CollapseItem></Collapse>
   <div class="word-grid"><article v-for="w in m.filtered" :key="w.id" class="word-card" :class="{pending:!m.mastered[w.id]}"><Tag>{{m.mastered[w.id]?'已掌握':'待掌握'}}</Tag><h3><Button @click="a.word(w.id)">{{w.en}}</Button></h3><p>{{w.pos}} {{w.cn}}</p></article></div>
   <Collapse v-model="expanded"><CollapseItem title="继续学习与考核" name="practice-tools"><div class="actions"><Button @click="a.continue">继续上次学习</Button><Button @click="a.startQuiz('lesson','all')">词汇综合考核</Button><Button @click="a.startQuiz('real')">近五年相关真题</Button></div><article v-for="g in m.groups" :key="g.id"><h3>{{g.title}}</h3><p>{{g.sub}} · 最佳 {{m.best[g.id]||0}}%</p><div class="actions"><Button @click="a.cards(g.id)">学习卡片</Button><Button @click="a.startQuiz('lesson',g.id)">本关考核</Button></div></article></CollapseItem></Collapse>
   <Popup v-model:show="wordFilter" position="bottom" round teleport="body"><Picker title="词条筛选" :columns="filterOptions" :model-value="[m.masteryFilter]" @confirm="({selectedValues})=>{wordFilter=false;a.masteryFilter(selectedValues[0])}"><template #cancel><Button icon="cross" aria-label="关闭词条筛选" @click="wordFilter=false"/></template></Picker></Popup>
  </section>

  <section v-else-if="m.view==='knowledge'" class="course-panel"><h2>阅读导学与语法微课</h2><article v-for="lesson in m.lessons" :key="lesson.id"><h3>{{lesson.title}}</h3><p>已阅读 {{lesson.cards.filter(c=>m.seen.includes(c.id)).length}} / {{lesson.cards.length}} 张 · 最佳 {{m.best[lesson.id]||0}}%</p><div class="actions"><Button @click="a.cards(lesson.id)">进入学习</Button><Button @click="a.startQuiz('lesson',lesson.id)">本关考核</Button></div></article></section>
  <section v-else-if="m.view==='card'&&m.card" class="course-panel"><div class="heading"><p>{{m.deck.title}} · {{m.cardIndex+1}} / {{m.deck.count}}</p><Button icon="cross" :aria-label="word?'关闭词卡':'关闭微课'" @click="a.open(word?'library':'knowledge')"/></div>
   <template v-if="word">
    <section v-if="!m.wordRun" data-word-phase="ready"><h2>准备记住这个词</h2><p class="meaning">{{word.cn}}</p><p>限时记忆后完成七次独立默写，再验证适用的复数形式、词义与词类。</p><RadioGroup :model-value="m.settings.memorySeconds" direction="horizontal" @update:model-value="v=>a.setting('memorySeconds',v)"><Radio :name="10">10 秒</Radio><Radio :name="15">15 秒</Radio></RadioGroup><Button type="primary" @click="a.startWord">开始记忆</Button><p v-if="m.mastered[word.id]">已掌握，可重新检测。</p></section>
    <section v-else-if="m.wordRun.phase==='memorize'" data-word-phase="memorize"><p role="timer" aria-label="英文显示剩余时间">专心记忆 · {{m.remaining}} 秒后自动隐藏</p><h2 class="english">{{word.en}}</h2><p>{{word.phon}} · {{word.pos}}</p><p class="meaning">{{word.cn}}</p><p v-if="m.wordDescription.plurals.length">复数：{{m.wordDescription.plurals.join(' / ')}}</p><h3>本词知识点</h3><p>{{word.tip}}</p><p class="english-example">{{word.ex}}</p><p>{{word.zh}}</p><div class="actions"><Button @click="a.speakWord">朗读单词</Button><Button @click="a.speakExample">跟读例句</Button></div></section>
    <section v-else-if="m.wordRun.phase==='recall'" data-word-phase="recall"><h2>这个词怎么写？</h2><p class="meaning">{{word.cn}}</p><p>{{word.pos}} · 只看中文，独立回忆英文。</p><p>第 {{m.wordRun.answers.length+1}} / 7 次 · 已提交的内容隐藏，结束后统一显示。</p><form @submit.prevent="a.submitRecall"><Field :key="m.wordRun.answers.length" :model-value="m.wordRun.input" :label="'第 '+(m.wordRun.answers.length+1)+' / 7 次'" autocomplete="off" autocorrect="off" autocapitalize="off" :spellcheck="false" maxlength="120" @update:model-value="a.recallInput"/><Button type="primary" native-type="submit">{{m.wordRun.answers.length===6?'提交第7次，查看结果':'确认本次默写'}}</Button></form></section>
    <section v-else-if="m.wordRun.phase==='verify'" :data-stage="m.verifyStage"><p>拼写 {{m.verification.answers.length}} / 7</p><template v-if="m.verifyStage==='recall'"><h2>{{word.cn}}</h2><p>连续正确默写七次，答错后重新累计。</p><form @submit.prevent="a.submitVerify"><Field :model-value="m.verifyInput" label="英文默写" autocomplete="off" autocorrect="off" autocapitalize="off" :spellcheck="false" @update:model-value="a.verifyInput"/><Button native-type="submit" type="primary">提交默写</Button></form></template><template v-else-if="m.verifyStage==='plural'"><h2 class="english">{{word.en}}</h2><p>默写复数形式，中文释义已隐藏。</p><form @submit.prevent="a.submitVerify"><Field :model-value="m.verifyInput" label="复数形式" autocomplete="off" autocorrect="off" autocapitalize="off" :spellcheck="false" @update:model-value="a.verifyInput"/><Button native-type="submit" type="primary">确认复数</Button></form></template><template v-else><h2 class="english">{{word.en}}</h2><Field :model-value="m.verification.draft" label="词义和词类口述" type="textarea" rows="5" maxlength="2000" :disabled="m.busy" @update:model-value="a.oralDraft"/><div class="actions"><Button type="primary" :loading="m.busy" :disabled="m.busy" @click="a.gradeOral">提交口述验证</Button><Button v-if="m.busy" @click="a.cancel">取消等待</Button></div><section v-if="m.verification.oral"><h3>批改结果</h3><p>词义：{{m.verification.oral.meaningPassed?'正确':'需巩固'}} · 词类：{{m.verification.oral.posPassed?'正确':'需巩固'}}</p><p>{{m.verification.oral.feedback}}</p><p v-for="(error,i) in m.verification.oral.errors" :key="i">{{error}}</p><div class="actions"><Button @click="a.retrySave">重试保存</Button><Button :disabled="m.busy" @click="a.nextWord">下一个单词</Button></div></section></template></section>
    <section v-else data-word-phase="result"><h2>{{m.wordCorrect.every(Boolean)?'七次全对':'本轮还需巩固'}}</h2><p>{{m.wordCorrect.filter(Boolean).length}} / 7</p><Cell v-for="(answer,i) in m.wordRun.answers" :key="i" :title="'第 '+(i+1)+' 次：'+answer" :value="m.wordCorrect[i]?'正确':'错误'"/><p v-if="m.mastered[word.id]">已掌握记录保留。</p><h3 class="english">{{word.en}}</h3><p>{{word.phon}} · {{word.pos}} {{word.cn}}</p><p>{{word.tip}}</p><p>{{word.ex}} {{word.zh}}</p><div class="actions"><Button @click="a.retryWord">再记忆、再测一轮</Button><Button @click="a.masteryFilter('mastered');a.open('library')">已掌握词库</Button></div><section v-if="m.wordEfficiency[word.id]"><h3>本词掌握时间与效率</h3><p>累计有效学习 {{duration(m.wordEfficiency[word.id].totalMs)}} · {{m.wordEfficiency[word.id].rounds}} 轮 · 达标 {{m.wordEfficiency[word.id].passes}} 次</p><p v-if="m.wordEfficiency[word.id].first">首次掌握：{{duration(m.wordEfficiency[word.id].first.ms)}} · {{m.wordEfficiency[word.id].first.rounds}} 轮 {{m.wordEfficiency[word.id].first.complete?'完整计时':'仅新版计时部分'}}</p><p v-if="m.wordEfficiency[word.id].last">最近掌握：{{duration(m.wordEfficiency[word.id].last.ms)}} · {{m.wordEfficiency[word.id].last.rounds}} 轮</p></section></section>
    <Collapse v-if="!m.wordRun||['memorize','result'].includes(m.wordRun.phase)" v-model="expanded"><CollapseItem :title="'本词知识与考核 · '+m.practice.length+' 道常考题'" name="practice"><p>{{m.focus?.target||word.tip}}</p><ol><li v-for="item in m.practice" :key="item.id">{{item.point}} · {{source(item.question)}}</li></ol><div class="actions"><Button @click="a.startQuiz('word',word.id)">开始本词5题考核</Button><Button v-if="m.focus?.lesson" @click="a.cards(m.focus.lesson)">关联知识</Button></div><h3>近五年相关原题资料</h3><p>{{m.examNote}}</p><article v-for="item in m.related" :key="item.id"><p>{{source(item)}}</p><p>{{item.matchNote}}</p><h4>{{item.q}}</h4><ol v-if="item.opts" type="A"><li v-for="(option,j) in item.opts" :key="j">{{option}}</li></ol><Button @click="a.startQuiz('single',item.id)">独立做这题</Button></article><p v-if="!m.related.length">暂无与本词匹配且已核实来源的近五年真题，可先完成上面的五道补充题。</p></CollapseItem></Collapse>
   </template>
   <template v-else><h2>{{m.card.title}}</h2><p>{{m.card.rule}}</p><article v-for="(example,i) in m.card.examples" :key="i"><p class="english-example">{{example[0]}}</p><p>{{example[1]}}</p></article><p>易错提醒：{{m.card.trap}}</p><Button @click="a.startQuiz('lesson',m.deck.id)">本关考核</Button></template><div v-if="!m.wordLocked" class="actions"><Button :disabled="m.cardIndex===0" @click="a.previous">上一张</Button><Button @click="a.next">{{m.cardIndex===m.deck.count-1?(word?'返回词库':'进入本关考核'):'下一张'}}</Button></div><p v-else>一次专注一个词，本轮进度自动保存。</p>
  </section>
  <section v-else-if="m.view==='quiz'&&q" class="course-panel"><p>{{m.quiz.title}} · {{m.quiz.index+1}} / {{m.quiz.items.length}} · 已得 {{m.quiz.score}} 分</p><p>{{m.quiz.mode==='word'?'本词5题，答对4题应用达标，拼写掌握仍须完整验证。':'每题1分，80%达标。先独立作答，再看解析。'}}</p><p>{{source(q)}}</p><a v-if="q.source?.url&&/^https?:\/\//.test(q.source.url)" :href="q.source.url" target="_blank" rel="noopener noreferrer">核对来源</a><h2>{{q.q}}</h2><RadioGroup v-if="q.type==='choice'" :model-value="m.quiz.picked" :disabled="m.quiz.answered" @update:model-value="a.pick"><CellGroup><Cell v-for="(option,i) in q.opts" :key="i" :title="option" clickable @click="!m.quiz.answered&&a.pick(i)"><template #right-icon><Radio :name="i"/></template></Cell></CellGroup></RadioGroup><form @submit.prevent="a.submitQuiz"><Field v-if="q.type!=='choice'" :model-value="m.quiz.input" label="填写英文答案" :disabled="m.quiz.answered" autocomplete="off" autocapitalize="off" :spellcheck="false" @update:model-value="a.quizInput"/><section v-if="m.quiz.answered" aria-live="polite"><h3>{{m.quiz.correct?'答对了':'本题需巩固'}}</h3><p>正确答案：{{right(q)}}</p><p>{{q.exp}}</p><p v-if="q.practiceBasis">考点依据：{{q.practiceBasis.rule}}</p></section><Button native-type="submit" type="primary">{{m.quiz.answered?(m.quiz.index===m.quiz.items.length-1?'查看战绩':'下一题'):'确认作答'}}</Button></form></section>
  <section v-else-if="m.view==='result'&&m.quiz" class="course-panel"><h2>{{m.quiz.title}} · {{m.quiz.score}} / {{m.quiz.items.length}}</h2><p>正确率 {{Math.round(m.quiz.score/m.quiz.items.length*100)}}%</p><article v-for="answer in m.quiz.answers.filter(row=>!row.correct)" :key="answer.id"><h3>{{m.quiz.items.find(q=>q.id===answer.id).q}}</h3><p>你的作答：{{answer.your}}</p><p>正确答案：{{right(m.quiz.items.find(q=>q.id===answer.id))}}</p><p>{{m.quiz.items.find(q=>q.id===answer.id).exp}}</p></article><p>本轮有效答题 {{duration(m.quiz.answers.reduce((sum,row)=>sum+row.activeMs,0))}} · {{(m.quiz.answers.filter(row=>row.correct).length/Math.max(1,m.quiz.answers.reduce((sum,row)=>sum+row.activeMs,0))*60000).toFixed(2)}} 正确题 / 分钟</p><div class="actions"><Button @click="a.feynman()">概念复述</Button><Button @click="a.retryQuiz">再练一轮</Button><Button @click="a.open('wrongbook')">错题本</Button><Button @click="a.open('library')">返回词库</Button></div></section>
  <section v-else-if="m.view==='wrongbook'" class="course-panel"><h2>待巩固错题 · {{m.wrongs.length}}</h2><Button v-if="m.wrongs.length" @click="a.startQuiz('review')">重练全部错题</Button><p>再次答对后移出待巩固列表，历史成绩保留。</p><article v-for="item in m.wrongs" :key="item.id"><h3>{{item.q}}</h3><p>{{source(item)}}</p><p>你的作答：{{item.your}}</p><p>正确答案：{{right(item)}}</p><p>{{item.exp}}</p><Button @click="a.startQuiz('single',item.id)">只练这题</Button></article><h3>最近10次战绩</h3><Cell v-for="(row,i) in m.records.slice(-10).reverse()" :key="i" :title="row.title" :label="new Date(row.at).toLocaleString('zh-CN')" :value="row.rank+' · '+row.score+'/'+row.total"/></section>
  <section v-else-if="m.view==='feynman'" class="course-panel"><div class="heading"><h2>用自己的话讲清楚</h2><Button icon="cross" aria-label="关闭概念复述" @click="a.open('library')"/></div><Field :model-value="m.topic.title" label="选择概念" readonly is-link @click="picker=true"/><p>{{m.topic.ask}}</p><Field :model-value="m.feynmanDraft" type="textarea" label="你的复述" rows="8" maxlength="5000" :disabled="m.busy" @update:model-value="a.feynmanDraft"/><div class="actions"><Button type="primary" :loading="m.busy" :disabled="m.busy" @click="a.gradeFeynman">提交AI评分</Button><Button v-if="m.busy" @click="a.cancel">取消等待</Button><Button @click="a.selfCheck">按清单自查</Button></div><section v-if="m.showSelf"><h3>对照清单，自己检查</h3><CheckboxGroup :model-value="m.selfChecks" @update:model-value="a.checks"><Checkbox v-for="(check,i) in m.topic.checks" :key="i" :name="i">{{check}}</Checkbox></CheckboxGroup><Collapse v-model="expanded"><CollapseItem title="查看参考讲法" name="sample"><p>{{m.topic.sample}}</p></CollapseItem></Collapse></section><section v-if="m.feynmanResult"><h3>本次理解反馈 {{m.feynmanResult.score}} / 100</h3><h4>讲清楚的地方</h4><p v-for="(good,i) in m.feynmanResult.good" :key="i">{{good}}</p><h4>可以补强的地方</h4><p v-for="(gap,i) in m.feynmanResult.gap" :key="i">{{gap}}</p><p>老师追问：{{m.feynmanResult.question}}</p><p>{{m.feynmanResult.comment}}</p></section></section>
  <section v-else-if="m.view==='doubts'" class="course-panel"><div class="heading"><h2>我有疑问 · Unit 3</h2><Button icon="cross" aria-label="关闭答疑" @click="a.open('library')"/></div><p>当前单元仅作背景，可询问其他问题。</p><article v-for="(entry,i) in m.doubt.messages" :key="i"><h3>{{entry.role==='assistant'?'老师的解释':'我的问题'}}</h3><p class="preserve">{{entry.text}}</p></article><Field :model-value="m.doubt.draft" type="textarea" label="我的问题" rows="5" maxlength="2000" :disabled="m.busy" @update:model-value="a.doubtDraft"/><div class="actions"><Button type="primary" :loading="m.busy" :disabled="m.busy" @click="a.ask">发送问题</Button><Button v-if="m.busy" @click="a.cancel">取消等待</Button></div></section>
  <section v-else-if="m.view==='study'" class="course-panel"><div class="heading"><h2>学习日历与成长</h2><Button icon="cross" aria-label="关闭学习日历" @click="a.open('library')"/></div><Calendar :poppable="false" :show-confirm="false" :min-date="new Date(2020,0,1)" :max-date="new Date()" switch-mode="month" :style="{height:'420px'}" :formatter="formatter" @select="a.calendarDay"/><Button @click="a.calendarDay(new Date())">查看今天记录</Button><h3>{{m.date}} · 学习摘要</h3><p>当天有效学习 {{duration(m.learningTime.days[m.date])}} · 新增掌握 {{Object.values(day?.words||{}).filter(row=>row.gained).length}} 个 · 微课 {{day?.cards.length||0}} 张</p><article v-for="(row,id) in day?.words||{}" :key="id"><h4>{{m.words.find(w=>w.id===id)?.en}} · {{row.lastPassed?'达标':'需巩固'}}</h4><p>检测 {{row.attempts}} 次 · 达标 {{row.passes}} 次</p><p v-if="row.masteryTiming">当日掌握 {{duration(row.masteryTiming.ms)}} · {{row.masteryTiming.rounds}} 轮</p><Button @click="a.word(id)">复习这个词</Button></article><Cell v-for="(row,id) in day?.quizzes||{}" :key="id" :title="row.title" :label="'考核 '+row.attempts+' 次 · 正确 '+row.correct+'/'+row.total+' · 最高 '+row.best+'%'"/><Cell v-for="(row,id) in day?.points||{}" :key="id" :title="row.label" :label="'正确 '+row.correct+'/'+row.total+(row.timing?' · 答题 '+duration(row.timing.ms):'')"/><Cell v-for="(row,id) in day?.feynman||{}" :key="id" :title="m.topics.find(t=>t.id===id)?.title" :label="'复述 '+row.attempts+' 次 · 最高 '+row.best+' / 100'"/><h3>掌握成长曲线</h3><svg viewBox="0 0 680 180" class="growth" role="img" aria-label="单词掌握成长曲线"><path :d="curve" fill="none" stroke="#22634b" stroke-width="3"/><text x="35" y="175">{{changes[0]?.date||'暂无带日期记录'}}</text></svg><p v-if="m.studyHistory.baseline.length">{{m.studyHistory.baseline.length}} 个旧记录缺少日期，保留为历史起点。</p><Tabs :active="m.metric" @change="a.metric"><Tab title="每日新增" name="daily"/><Tab title="累计掌握" name="total"/><Tab title="每日考点达标" name="points"/></Tabs><Cell v-for="row in changes" :key="row.date" :title="row.date" :label="'新增词 '+row.newCount+' · 累计词 '+row.total+' · 达标考点 '+row.points+' · 考核 '+row.quizzes+' 轮'" is-link @click="a.calendarDay(new Date(row.date+'T12:00:00'))"/><template v-if="m.metric==='points'"><Cell v-for="(row,i) in efficiencyPoints" :key="i" :title="row.label" :label="'正确 '+row.correct+'/'+row.total+' · '+(row.total?Math.round(row.correct/row.total*100):0)+'% · 有效答题 '+duration(row.ms)"/></template><RadioGroup :model-value="m.range" direction="horizontal" @update:model-value="a.range"><Radio :name="7">近7天</Radio><Radio :name="30">近30天</Radio><Radio :name="90">近90天</Radio></RadioGroup><Collapse v-model="expanded"><CollapseItem title="每日有效学习与单词掌握效率" name="efficiency"><p v-for="(ms,key) in m.learningTime.days" :key="key">{{key}} · {{duration(ms)}}</p><article v-for="(row,id) in m.wordEfficiency" :key="id"><h4>{{m.words.find(w=>w.id===id)?.en}}</h4><p>累计 {{duration(row.totalMs)}} · {{row.rounds}} 轮 · 达标 {{row.passes}} 次</p><p v-if="row.first">首次掌握 {{duration(row.first.ms)}} · {{row.first.rounds}} 轮 {{row.first.complete?'完整计时':'仅新版部分'}}</p><p v-if="row.last">最近掌握 {{duration(row.last.ms)}} · {{row.last.rounds}} 轮</p></article></CollapseItem></Collapse></section>
  <section v-else-if="m.view==='settings'" class="course-panel"><StudentCourseSettings :services="services" @close="a.open('library')"/><h3>词汇学习设置</h3><Checkbox :model-value="m.settings.autoSpeak" @update:model-value="value=>a.setting('autoSpeak',value)">记忆时自动朗读</Checkbox><RadioGroup :model-value="m.settings.rate" direction="horizontal" @update:model-value="value=>a.setting('rate',value)"><Radio :name="0.7">慢速</Radio><Radio :name="0.85">稍慢</Radio><Radio :name="1">正常</Radio></RadioGroup><Button @click="confirmed=false;reset=true">重置Unit3学习进度</Button><p>重置默写、微课、考核、错题、复述草稿、日历与效率，AI配置、奖励及独立答疑记录保留。</p></section>
  <section v-else-if="m.view==='rewards'" class="course-panel"><div class="heading"><h2>掌握与奖励</h2><Button icon="cross" aria-label="关闭掌握与奖励" @click="a.open('library')"/></div><p>单词默写50% + 句子闯关50%；其他学习活动不计入章节掌握度，旧成绩和已获得奖励保留。</p><template v-if="m.rewardLedger"><p>已获得 {{m.rewardAmounts.game}} 分钟游戏 / {{(m.rewardAmounts.cash/100).toFixed(2)}} 元红包</p><p>已核销 {{m.rewardLedger.paidGame}} 分钟 / {{(m.rewardLedger.paidCash/100).toFixed(2)}} 元；可领 {{m.rewardAmounts.availableGame}} 分钟 / {{(m.rewardAmounts.availableCash/100).toFixed(2)}} 元</p><Field v-model="game" label="游戏总分钟" type="number" :disabled="m.rewardLocked"/><Field v-model="cash" label="红包总元" type="number" :disabled="m.rewardLocked"/><Checkbox v-model="enabled" :disabled="m.rewardLocked">启用奖励累计</Checkbox><Button :disabled="m.rewardLocked" @click="a.saveReward(game,cash,enabled)">保存本单元奖励</Button><Field v-model="parent" label="家长称呼" maxlength="30"/><Checkbox v-model="parentConfirm">我是家长，确认已实际兑现本次额度</Checkbox><div class="actions"><Button :disabled="!parentConfirm||!m.rewardAmounts.availableGame" @click="a.redeemReward('game',parent,parentConfirm)">核销游戏时间</Button><Button :disabled="!parentConfirm||!m.rewardAmounts.availableCash" @click="a.redeemReward('cash',parent,parentConfirm)">核销红包</Button></div><p>本页只记账，不转账或控制游戏；家长确认不提供身份验证。已获奖励不会因重学重复累计。</p><p v-for="(row,i) in m.rewardLedger.history" :key="i">{{row.legacy?'已承接旧版整单元奖励':new Date(row.at).toLocaleString('zh-CN')+' · '+row.parent+' · '+(row.kind==='game'?row.amount+' 分钟':(row.amount/100).toFixed(2)+' 元')}}</p></template><p v-else role="alert">{{m.rewardError}}</p></section>
  <Popup v-model:show="picker" position="bottom" round teleport="body"><Picker title="选择复述概念" :columns="topicColumns" :model-value="[m.topic.id]" @confirm="selectTopic" @cancel="picker=false"><template #cancel><Button icon="cross" aria-label="关闭概念选择" class="cross" @click="picker=false"/></template></Picker></Popup><Popup v-model:show="unitPicker" position="bottom" round teleport="body"><Picker title="切换单元" :columns="unitColumns" :model-value="['english-8a-03']" @confirm="selectUnit" @cancel="unitPicker=false"><template #cancel><Button icon="cross" aria-label="关闭单元选择" class="cross" @click="unitPicker=false"/></template></Picker></Popup>
  <Dialog v-model:show="reset" title="重置Unit3学习进度"><div class="reset-content"><p>清除本单元学习记录与日历，保留AI配置、独立答疑和已获奖励。</p><Checkbox v-model="confirmed">我确认重置Unit3进度</Checkbox></div><template #footer><div class="actions reset-content"><Button icon="cross" aria-label="关闭重置确认" class="cross" @click="reset=false;confirmed=false"/><Button type="danger" :disabled="!confirmed" @click="doReset">重置本单元进度</Button></div></template></Dialog>
  <Collapse v-model="expanded" class="course-more"><CollapseItem title="更多课堂工具" name="tools"><div class="actions"><Button @click="a.startQuiz('exam')">综合考核</Button><Button @click="a.open('wrongbook')">错题本 {{m.wrongs.length}}</Button><Button @click="a.open('doubts')">我有疑问</Button><Button @click="a.open('study')">学习日历</Button><Button @click="reward">掌握与奖励</Button><Button @click="a.open('settings')">学习设置</Button></div></CollapseItem></Collapse>
